"""Registrar leituras e inspeção visual do lote C-01 (registro 131)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');ins=load(A/'imagens-inspecionadas-primeira-prova-visual.json')['primeira_prova'];N=len(m['paginas']);assert N==9
cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)};same={i for i in cur if ins[str(i)]==cur[i]};assert same==set(range(1,10)),same
notes={1:'Abertura da ficha de preparação, campos com linhas e quadro de pessoas.',2:'Quadros de lugares, informação e consequências com altura de escrita; perigos.',3:'Conferência, durante e depois do jogo; abertura da folha de condução.',4:'Para cada tentativa, resultado no teste, conversa e proposta inesperada.',5:'Combate, dúvida de regra com quadro e encerramento.',6:'Abertura do registro de estado com quadro de reservas e campos.',7:'Queda em andamento, saída e recuperação; abertura da linha de continuidade.',8:'Modelo com quadro e campos; entregar ou retomar; sugestões.',9:'Quadro de providências e exemplo entre três missões.'}
save('revisao-final.json',{'registro':131,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das quatro fichas e das regras citadas, quatro cópias, remissões para os capítulos novos e clareza.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura da prova completa, trechos alterados no contexto e varredura de crase, repetições e termos de produção; nenhuma alteração necessária.'}],'ajuste_de_diagramacao':'Linhas de preenchimento nos campos das três fichas de registro e altura de escrita nas células vazias; a folha de condução fica sem linhas.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if False else 'Inspeção direta na primeira prova; imagem idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','Títulos de ficha no pé das páginas 3 e 7 seguidos do conteúdo na página seguinte; reavaliar na integração.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s002':[1,3],'s005':[3,5],'s024':[6,7],'s016':[7,9]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':131,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':131,'lote':'C-01','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':59,'casos_pendentes':0,'lotes_pendentes':0,'consultas_revistas':4,'consultas_pendentes':13,'consultas_complementares_pendentes':17,'etapa_6':'em andamento','proximo_lote':'C-02','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
print(json.dumps({'paginas_inspecionadas':N,'registros':len(changes),'casos':4},ensure_ascii=False))
